    try {
      assertStoredThread(grantIdentity(currentGrant(entry.originatingMcpGrant)), entry.app.producing.threadId);
      return true;
    } catch {
      clearMcpAppContexts(undefined, undefined, entry.originatingMcpGrant.grantId);
      return false;
    }
  }));
