                  ...input.context.input.providerThread,
                  providerSessionId: session.id,
                  ...(clearConversationHead ? { nativeConversationHeadRef: null } : {}),
                  ...(nativeThreadId !== null && goalsByNativeThread.has(nativeThreadId)
