                    : {}),
                  firstRunOrdinal:
                    input.context.input.providerThread.firstRunOrdinal ??
                    input.context.input.runOrdinal,
                  lastRunOrdinal: input.context.input.runOrdinal,
                  pendingBackgroundTasks: claudePendingBackgroundTasksFromRoster(
                    roster,
