          const userResults = claudeToolResultBlocksFromUserMessage(message);
          if (
            message.type === "user" &&
            userResults.length > 0 &&
            userResults.length === message.message.content.length &&
            userResults.every(
              (toolResult) => findToolCall(settled, toolResult.tool_use_id) !== undefined,
